"""Reader-writer lock with writer preference, using only the stdlib threading module.

Semantics:
- Many readers may hold the lock concurrently.
- A writer holds the lock exclusively.
- Once a writer is waiting, newly arriving readers queue behind it
  (no writer starvation).
"""

import threading


class RWLock:
    def __init__(self):
        self._cond = threading.Condition()
        self._readers = 0        # readers currently holding the lock
        self._writer = False     # is a writer currently holding the lock?
        self._writers_waiting = 0

    # -- reader side -------------------------------------------------------
    def r_acquire(self):
        with self._cond:
            while self._writer or self._writers_waiting:
                # Writer active or waiting -> queue behind it.
                self._cond.wait()
            self._readers += 1

    def r_release(self):
        with self._cond:
            self._readers -= 1
            if self._readers == 0:
                self._cond.notify_all()

    # -- writer side -------------------------------------------------------
    def w_acquire(self):
        with self._cond:
            self._writers_waiting += 1
            try:
                while self._writer or self._readers:
                    self._cond.wait()
                self._writer = True
            finally:
                self._writers_waiting -= 1

    def w_release(self):
        with self._cond:
            self._writer = False
            # Wake everyone; waiting writers beat waiting readers because
            # readers block whenever _writers_waiting > 0.
            self._cond.notify_all()

    # -- context managers ----------------------------------------------------
    def read(self):
        return _ReadContext(self)

    def write(self):
        return _WriteContext(self)


class _ReadContext:
    __slots__ = ("_lock",)

    def __init__(self, lock):
        self._lock = lock

    def __enter__(self):
        self._lock.r_acquire()
        return None

    def __exit__(self, exc_type, exc, tb):
        self._lock.r_release()
        return False


class _WriteContext:
    __slots__ = ("_lock",)

    def __init__(self, lock):
        self._lock = lock

    def __enter__(self):
        self._lock.w_acquire()
        return None

    def __exit__(self, exc_type, exc, tb):
        self._lock.w_release()
        return False

